          }
        ],
        "responses": {
          "200": {
            "$ref": "#/responses/GenerateKeyResponse"
          }
        }
      },
      "delete": {
        "description": "Deletes the key with the passed public key from the wallet.",
        "produces": [
          "application/json"
        ],
        "summary": "Delete a key",
        "operationId": "DeleteKey",
        "parameters": [
          {
            "name": "Delete Key Request",
            "in": "body",
