      "delete": {
        "description": "Deletes multisig preimage information for the passed address from the wallet.\n",
        "produces": [
          "application/json"
        ],
        "summary": "Delete a multisig",
        "operationId": "DeleteMultisig",
        "parameters": [
          {
            "name": "Delete Multisig Request",
