            }
          }
        ],
        "responses": {
          "200": {
            "$ref": "#/responses/ImportMultisigResponse"
          }
        }
      }
    },
    "/v1/multisig/list": {
      "post": {
        "description": "Lists all of the multisig accounts whose preimages this wallet stores",
